"Financial Accounting": [
  { text:"The accounting equation is expressed as:", A:"Assets = Liabilities - Capital", B:"Assets = Capital + Liabilities", C:"Capital = Assets + Liabilities", D:"Liabilities = Assets + Capital", correct:"B", topic:"Basic Concepts", difficulty:"easy" },
  { text:"A document showing money owed by a business to its suppliers is recorded under:", A:"Assets", B:"Liabilities", C:"Capital", D:"Drawings", correct:"B", topic:"Basic Concepts", difficulty:"easy" },
  { text:"The book of original entry in which all transactions are first recorded is the:", A:"Ledger", B:"Trial balance", C:"Journal", D:"Balance sheet", correct:"C", topic:"Books of Accounts", difficulty:"easy" },
  { text:"A trial balance is prepared mainly to:", A:"calculate tax", B:"check the arithmetic accuracy of ledger accounts", C:"record cash sales", D:"replace the balance sheet", correct:"B", topic:"Trial Balance", difficulty:"medium" },
  { text:"Depreciation refers to the:", A:"increase in value of an asset", B:"reduction in value of a fixed asset over time", C:"cash paid to owners", D:"total revenue earned", correct:"B", topic:"Depreciation", difficulty:"medium" },
  { text:"Money withdrawn by the owner of a business for personal use is called:", A:"Capital", B:"Drawings", C:"Revenue", D:"Liability", correct:"B", topic:"Basic Concepts", difficulty:"easy" },
  { text:"The financial statement that shows a business's assets, liabilities and capital at a point in time is the:", A:"Trading account", B:"Profit and loss account", C:"Balance sheet", D:"Cash book", correct:"C", topic:"Financial Statements", difficulty:"easy" },
  { text:"The double-entry principle states that every transaction affects:", A:"one account only", B:"at least two accounts", C:"only cash accounts", D:"no accounts", correct:"B", topic:"Basic Concepts", difficulty:"easy" },
  { text:"Gross profit is calculated as:", A:"Sales - Cost of goods sold", B:"Sales + Expenses", C:"Net profit - Expenses", D:"Capital - Liabilities", correct:"A", topic:"Trading Account", difficulty:"medium" },
  { text:"A book used to record small cash payments is called the:", A:"Ledger", B:"Petty cash book", C:"Journal", D:"Sales day book", correct:"B", topic:"Books of Accounts", difficulty:"easy" },
  { text:"An asset that can easily be converted to cash within a year is called a:", A:"Fixed asset", B:"Current asset", C:"Intangible asset", D:"Contingent asset", correct:"B", topic:"Assets and Liabilities", difficulty:"easy" },
  { text:"Bank reconciliation is done to:", A:"increase bank charges", B:"match the cash book balance with the bank statement balance", C:"prepare the trial balance", D:"calculate depreciation", correct:"B", topic:"Bank Reconciliation", difficulty:"medium" },
  { text:"Which of these is an example of a liability?", A:"Cash in hand", B:"Loan from bank", C:"Machinery", D:"Debtors", correct:"B", topic:"Assets and Liabilities", difficulty:"easy" },
  { text:"The process of transferring entries from the journal to the ledger is called:", A:"Balancing", B:"Posting", C:"Casting", D:"Reconciling", correct:"B", topic:"Books of Accounts", difficulty:"medium" },
  { text:"Net profit is obtained by deducting ___ from gross profit.", A:"cost of goods sold", B:"expenses", C:"capital", D:"drawings", correct:"B", topic:"Profit and Loss Account", difficulty:"medium" },
  { text:"An amount owed to the business by customers is called:", A:"Creditors", B:"Debtors", C:"Capital", D:"Liabilities", correct:"B", topic:"Basic Concepts", difficulty:"easy" },
  { text:"The straight-line method of depreciation charges:", A:"a varying amount each year", B:"an equal amount of depreciation each year", C:"depreciation only in the first year", D:"no depreciation at all", correct:"B", topic:"Depreciation", difficulty:"medium" },
  { text:"A suspense account is opened mainly when:", A:"profit is very high", B:"the trial balance fails to balance", C:"a business closes down", D:"dividends are declared", correct:"B", topic:"Trial Balance", difficulty:"hard" },
  { text:"Capital in a business represents:", A:"money owed to creditors", B:"the owner's investment in the business", C:"total sales", D:"total expenses", correct:"B", topic:"Basic Concepts", difficulty:"easy" },
  { text:"Which of these best describes 'accrued expenses'?", A:"Expenses paid in advance", B:"Expenses incurred but not yet paid", C:"Income received in advance", D:"Income not yet earned", correct:"B", topic:"Adjustments", difficulty:"medium" },
],

